-- Snapshot of currently unpaid (pending/partial) Holded invoices, España
-- entity, as of 2026-09-22 (194 invoices, ~1.55M€ pending — 374k€ already
-- overdue). This table is NOT append-only like the others: the weekly sync
-- (Parte 5) upserts still-unpaid invoices and DELETEs any row whose
-- invoice got paid, cancelled, or no longer exists, so it always reflects
-- the current state, not a history.

on conflict (invoice_id) do update set
  document_number = excluded.document_number,
  contact_name = excluded.contact_name,
  due_date = excluded.due_date,
  total = excluded.total,
  payments_pending = excluded.payments_pending,
  pending_eur = excluded.pending_eur,
  status = excluded.status,
  updated_at = now();
